/** Rendering of the parsed document as JSON text or as a key listing. */

function cmp(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  for (let i = 0; i < x.length && i < y.length; i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}

const sortedKeys = (node) => [...node.map.keys()].sort(cmp)

function render(node, indent) {
  const pad = '  '.repeat(indent + 1)
  const end = '  '.repeat(indent)
  switch (node.t) {
    case 'table': {
      const keys = sortedKeys(node)
      if (!keys.length) return '{}'
      return '{\n' + keys.map((k) => `${pad}${JSON.stringify(k)}: ${render(node.map.get(k), indent + 1)}`).join(',\n') + '\n' + end + '}'
    }
    case 'array':
      if (!node.items.length) return '[]'
      return '[\n' + node.items.map((n) => pad + render(n, indent + 1)).join(',\n') + '\n' + end + ']'
    case 'string':
      return JSON.stringify(node.v)
    case 'integer':
      return node.v
    case 'float':
      return JSON.stringify(node.v)
    default:
      return String(node.v)
  }
}

export const toJson = (root) => render(root, 0) + '\n'

export function toKeys(root) {
  const lines = []
  const walk = (node, path) => {
    if (node.t === 'table') {
      for (const k of sortedKeys(node)) {
        const p = path === null ? k : `${path}.${k}`
        const child = node.map.get(k)
        lines.push(`${p} ${child.t}`)
        walk(child, p)
      }
    } else if (node.t === 'array') {
      node.items.forEach((child, i) => {
        const p = `${path}[${i}]`
        lines.push(`${p} ${child.t}`)
        walk(child, p)
      })
    }
  }
  walk(root, null)
  return lines.map((l) => l + '\n').join('')
}
