/** Parser for the configuration document. */

export class ParseError extends Error {
  constructor(message) {
    super(message)
    this.line = 0
  }
}

const fail = (m) => {
  throw new ParseError(m)
}
const newTable = () => ({ t: 'table', map: new Map(), header: false })
const isWs = (c) => c === ' ' || c === '\t'
const isBare = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let current = root
  let currentPath = []
  for (let i = 0; i < lines.length; i++) {
    try {
      const r = parseLine(lines[i], root, current, currentPath)
      if (r) [current, currentPath] = r
    } catch (e) {
      if (e instanceof ParseError) e.line = i + 1
      throw e
    }
  }
  return root
}

class Cursor {
  constructor(s) {
    this.s = s
    this.i = 0
  }
  get c() {
    return this.s[this.i]
  }
  ws() {
    while (isWs(this.c)) this.i++
  }
  /** True at the end of the line or where a comment starts. */
  atEnd() {
    return this.i >= this.s.length || this.c === '#' || this.c === ';'
  }
}

function parseLine(line, root, current, currentPath) {
  const cur = new Cursor(line)
  cur.ws()
  if (cur.atEnd()) return null
  if (cur.c === '[') return parseHeader(cur, root)
  const { parts } = parseDotted(cur)
  cur.ws()
  if (cur.c !== '=') fail('expected key = value')
  cur.i++
  cur.ws()
  const value = parseValue(cur, [...currentPath, ...parts])
  cur.ws()
  if (!cur.atEnd()) fail('trailing text after a value')
  assign(current, parts, value, currentPath)
  return null
}

function parseHeader(cur, root) {
  cur.i++
  const isArr = cur.c === '['
  if (isArr) cur.i++
  cur.ws()
  const { parts } = parseDotted(cur)
  cur.ws()
  if (cur.c !== ']') fail('unterminated table header')
  cur.i++
  if (isArr) {
    if (cur.c !== ']') fail('unterminated table header')
    cur.i++
  }
  cur.ws()
  if (!cur.atEnd()) fail('trailing text after a table header')

  let table = root
  const path = []
  for (let k = 0; k < parts.length; k++) {
    const key = parts[k]
    path.push(key)
    const last = k === parts.length - 1
    let node = table.map.get(key)
    if (last) {
      if (isArr) {
        if (!node) {
          node = { t: 'array', items: [], tables: true }
          table.map.set(key, node)
        } else if (node.t !== 'array' || !node.tables) fail(`${path.join('.')} is not an array of tables`)
        const fresh = newTable()
        fresh.header = true
        node.items.push(fresh)
        return [fresh, path]
      }
      if (!node) {
        node = newTable()
        table.map.set(key, node)
      } else if (node.t !== 'table') fail(`${path.join('.')} is not a table`)
      if (node.header) fail(`table ${path.join('.')} is defined twice`)
      node.header = true
      return [node, path]
    }
    table = step(table, key, path)
  }
}

/** Descend through `key`, creating a table when absent. */
function step(table, key, path) {
  let node = table.map.get(key)
  if (!node) {
    node = newTable()
    table.map.set(key, node)
    return node
  }
  if (node.t === 'array' && node.tables) return node.items[node.items.length - 1]
  if (node.t !== 'table') fail(`${path.join('.')} is not a table`)
  return node
}

function assign(table, parts, value, basePath) {
  const path = [...basePath]
  for (let k = 0; k < parts.length - 1; k++) {
    path.push(parts[k])
    table = step(table, parts[k], path)
  }
  path.push(parts[parts.length - 1])
  const key = parts[parts.length - 1]
  if (table.map.has(key)) fail(`key ${path.join('.')} is defined twice`)
  table.map.set(key, value)
}

function parseDotted(cur) {
  const parts = [parseName(cur)]
  for (;;) {
    const save = cur.i
    cur.ws()
    if (cur.c !== '.') {
      cur.i = save
      return { parts }
    }
    cur.i++
    cur.ws()
    parts.push(parseName(cur))
  }
}

function parseName(cur) {
  const c = cur.c
  if (c === '"') return parseBasic(cur)
  if (c === "'") return parseLiteral(cur)
  if (!isBare(c)) fail('expected a name')
  const start = cur.i
  while (isBare(cur.c)) cur.i++
  return cur.s.slice(start, cur.i)
}

function parseBasic(cur) {
  cur.i++
  let out = ''
  for (;;) {
    const c = cur.c
    if (c === undefined) fail('unterminated string')
    cur.i++
    if (c === '"') return out
    if (c !== '\\') {
      out += c
      continue
    }
    const e = cur.c
    if (e === undefined) fail('unterminated string')
    cur.i++
    const simple = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
    if (Object.hasOwn(simple, e)) out += simple[e]
    else if (e === 'u') {
      const hex = cur.s.slice(cur.i, cur.i + 4)
      if (!/^[0-9A-Fa-f]{4}$/.test(hex)) fail('invalid escape \\u')
      out += String.fromCharCode(parseInt(hex, 16))
      cur.i += 4
    } else {
      // a full code point, so a surrogate pair is reported whole
      const cp = String.fromCodePoint(cur.s.codePointAt(cur.i - 1))
      fail(`invalid escape \\${cp}`)
    }
  }
}

function parseLiteral(cur) {
  const end = cur.s.indexOf("'", cur.i + 1)
  if (end < 0) fail('unterminated string')
  const v = cur.s.slice(cur.i + 1, end)
  cur.i = end + 1
  return v
}

function parseValue(cur, path) {
  const c = cur.c
  if (cur.atEnd() || c === ',' || c === ']' || c === '}') fail('expected a value')
  if (c === '"') return { t: 'string', v: parseBasic(cur) }
  if (c === "'") return { t: 'string', v: parseLiteral(cur) }
  if (c === '[') return parseArray(cur, path)
  if (c === '{') return parseInline(cur, path)
  const start = cur.i
  while (cur.c !== undefined && !isWs(cur.c) && cur.c !== ',' && cur.c !== ']' && cur.c !== '}') cur.i++
  const tok = cur.s.slice(start, cur.i)
  if (tok === 'true' || tok === 'false') return { t: 'boolean', v: tok === 'true' }
  const D = '\\d+(?:_\\d+)*'
  if (new RegExp(`^[+-]?${D}$`).test(tok)) {
    return { t: 'integer', v: BigInt(tok.replace(/_/g, '')).toString() }
  }
  if (new RegExp(`^[+-]?${D}(?:\\.${D}(?:[eE][+-]?${D})?|[eE][+-]?${D})$`).test(tok)) {
    return { t: 'float', v: Number(tok.replace(/_/g, '')) }
  }
  fail(`invalid value ${tok}`)
}

function parseArray(cur, path) {
  cur.i++
  const items = []
  for (;;) {
    cur.ws()
    if (cur.atEnd()) fail('unterminated array')
    if (cur.c === ']') {
      cur.i++
      return { t: 'array', items, tables: false }
    }
    items.push(parseValue(cur, path))
    cur.ws()
    if (cur.c === ',') cur.i++
    else if (cur.c === ']') {
      cur.i++
      return { t: 'array', items, tables: false }
    } else fail('unterminated array')
  }
}

function parseInline(cur, path) {
  cur.i++
  const table = newTable()
  cur.ws()
  if (cur.atEnd()) fail('unterminated inline table')
  if (cur.c === '}') {
    cur.i++
    return table
  }
  for (;;) {
    cur.ws()
    if (cur.atEnd()) fail('unterminated inline table')
    const { parts } = parseDotted(cur)
    cur.ws()
    if (cur.c !== '=') fail('expected = in an inline table')
    cur.i++
    cur.ws()
    const value = parseValue(cur, [...path, ...parts])
    assign(table, parts, value, path)
    cur.ws()
    if (cur.c === ',') cur.i++
    else if (cur.c === '}') {
      cur.i++
      return table
    } else fail('unterminated inline table')
  }
}
